{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.RETAIL_JOURNEY_SPINE AS WITH order_base AS ( SELECT order_name, MAX(order_timestamp) AS order_timestamp, MAX(order_date) AS order_date, MAX(order_type) AS order_type, MAX(warehouse_name) AS warehouse_name, MAX(packed_timestamp) AS packed_timestamp, MIN(COALESCE(manifested_timestamp, packed_timestamp)) AS manifested_timestamp, COUNT(*) AS quantity, MAX(last_updated) AS last_updated FROM snitch_db.maplemonk.warehouse_sla_performance WHERE marketplace_mapped = \'STORE\' AND order_type <> \'NSO\' AND IFNULL(sla_status,\'\') NOT ILIKE \'%cancel%\' AND IFNULL(item_status,\'\') <> \'CANCELLED\' AND order_date >= \'2026-03-01\' GROUP BY order_name ), store_master AS ( SELECT so_code, store_name_format, state FROM snitch_db.maplemonk.gs_store_details ), order_with_store AS ( SELECT ob.*, sm.store_name_format AS final_store, sm.state, CASE WHEN sm.store_name_format ILIKE \'%FOCO%\' OR sm.store_name_format ILIKE \'%FOFO%\' THEN \'FRANCHISE\' ELSE \'OWN\' END AS store_channel FROM order_base ob LEFT JOIN store_master sm ON LEFT(ob.order_name, 6) = sm.so_code ), sto_own AS ( SELECT UPPER(TRIM(order_no)) AS order_key, new_bill_no AS shipment_bill, TRY_TO_DATE(bill_date,\'DD/MM/YYYY\') AS sto_bill_date, to_party, from_party FROM snitch_db.maplemonk.logic_final_sto WHERE IFNULL(origin,\'\') = \'WH-STORE\' AND IFNULL(bill_no,\'\') <> \'ST-4520\' QUALIFY ROW_NUMBER() OVER (PARTITION BY new_bill_no ORDER BY new_bill_no) = 1 ), awb_virtual AS ( SELECT DISTINCT UPPER(TRIM(order_no)) AS order_key, new_bill_no AS shipment_bill FROM snitch_db.maplemonk.logic_final_sto WHERE IFNULL(origin,\'\') = \'WH-VIRTUAL\' ), shipment_link AS ( SELECT o.order_name, o.store_channel, so.shipment_bill, so.sto_bill_date FROM order_with_store o JOIN sto_own so ON UPPER(TRIM(o.order_name)) = so.order_key WHERE o.store_channel = \'OWN\' UNION ALL SELECT o.order_name, o.store_channel, av.shipment_bill, NULL AS sto_bill_date FROM order_with_store o JOIN awb_virtual av ON UPPER(TRIM(o.order_name)) = av.order_key WHERE o.store_channel = \'FRANCHISE\' ), eshipz AS ( SELECT UPPER(TRIM(unique_order_id)) AS bill_key, tracking_number, status, eship_status, courier_partner, logistics_created_timestamp, logistics_delivery_timestamp, logistics_expected_delivery_date, tracking_pick_date, first_ofd_date, latest_ofd_date, delivery_attempts, pickup_attempts, tracking_link, tracking_status, tracking_sub_status, tracking_latest_location, tracking_latest_message, last_checkpoint_city, last_checkpoint_state, receiver_city, receiver_state, zone, pod_link, package_count, delivery_sla AS eshipz_delivery_sla, logistics_delivery_sla, final_status AS eshipz_final_status FROM SNITCH_DB.MAPLEMONK.FINAL_ESHIP_TRACKING WHERE IFNULL(is_reverse, FALSE) = FALSE QUALIFY ROW_NUMBER() OVER ( PARTITION BY UPPER(TRIM(unique_order_id)), tracking_number ORDER BY logistics_delivery_timestamp DESC NULLS LAST, tracking_pick_date DESC NULLS LAST ) = 1 ), sti AS ( SELECT UPPER(TRIM(bill_no)) AS bill_key, MIN(vouch_date) AS inwarded_date, SUM(item_quantity) AS sti_qty FROM snitch_db.maplemonk.logic_final_sti WHERE IFNULL(origin,\'\') ILIKE \'%-STORE\' GROUP BY UPPER(TRIM(bill_no)) ), rulebook AS ( SELECT order_name, best_tat, lane_classification, target_order_day, target_order_cutoff, target_handover_day, target_handover_cutoff, target_pickup_day, target_delivery_day, order_cutoff_ts, order_placement_sla, handover_deadline_ts, pickup_tat, ideal_delivery_date, delivery_tat, handover_sla, pickup_sla, delivery_sla, perfect_order_sla, invoice_number, merchandiser, sales_30d, rank, area_manager FROM snitch_db.maplemonk.distribution_analytics QUALIFY ROW_NUMBER() OVER (PARTITION BY order_name ORDER BY handover_deadline_ts DESC NULLS LAST) = 1 ), assembled AS ( SELECT o.order_name, o.order_timestamp, o.order_date, o.order_type, o.warehouse_name, o.final_store AS store, o.state, o.store_channel, o.packed_timestamp, o.manifested_timestamp, o.quantity, o.last_updated, sl.shipment_bill, sl.sto_bill_date, (rb.target_handover_day IS NOT NULL) AS rulebook_covered, COALESCE( rb.handover_deadline_ts, DATE_TRUNC(\'day\', o.order_timestamp) + INTERVAL \'2 day\' + INTERVAL \'18 hour\' ) AS handover_deadline_ts, rb.best_tat, rb.lane_classification, rb.target_order_day, rb.target_order_cutoff, rb.target_handover_day, rb.target_handover_cutoff, rb.target_pickup_day, rb.target_delivery_day, rb.order_cutoff_ts, rb.order_placement_sla, rb.pickup_tat, rb.ideal_delivery_date, rb.delivery_tat, rb.handover_sla, rb.pickup_sla, COALESCE(rb.delivery_sla, e.eshipz_delivery_sla) AS delivery_sla, rb.perfect_order_sla, e.logistics_expected_delivery_date AS delivery_target_edd, e.tracking_number, e.status, e.eship_status, e.courier_partner, e.logistics_created_timestamp, e.logistics_delivery_timestamp, e.logistics_expected_delivery_date, e.tracking_pick_date, e.first_ofd_date, e.latest_ofd_date, e.delivery_attempts, e.pickup_attempts, e.tracking_link, e.tracking_status, e.tracking_sub_status, e.tracking_latest_location, e.tracking_latest_message, e.last_checkpoint_city, e.last_checkpoint_state, e.receiver_city, e.receiver_state, e.zone, e.pod_link, e.package_count, e.logistics_delivery_sla, COALESCE(rb.invoice_number, sl.shipment_bill) AS invoice_number, COALESCE(e.eshipz_final_status, e.status) AS final_status, st.inwarded_date AS inwarded_date_raw, st.sti_qty AS sti_qty_raw, ROW_NUMBER() OVER ( PARTITION BY o.order_name, sl.shipment_bill ORDER BY e.tracking_number NULLS LAST ) AS awb_seq, rb.merchandiser, rb.sales_30d, rb.rank, rb.area_manager FROM order_with_store o LEFT JOIN shipment_link sl ON o.order_name = sl.order_name LEFT JOIN eshipz e ON UPPER(TRIM(sl.shipment_bill)) = e.bill_key LEFT JOIN sti st ON UPPER(TRIM(sl.shipment_bill)) = st.bill_key LEFT JOIN rulebook rb ON o.order_name = rb.order_name ) SELECT a.* EXCLUDE (inwarded_date_raw, sti_qty_raw, awb_seq), IFF(a.awb_seq = 1, a.inwarded_date_raw, NULL) AS inwarded_date, IFF(a.awb_seq = 1, a.sti_qty_raw, NULL) AS sti_qty, IFF(a.awb_seq = 1, a.quantity - a.sti_qty_raw, NULL) AS ex_short, CASE WHEN a.sti_qty_raw IS NOT NULL THEN \'INWARDED\' WHEN a.logistics_delivery_timestamp IS NOT NULL THEN \'DELIVERED\' WHEN a.tracking_pick_date IS NOT NULL THEN \'IN_TRANSIT\' WHEN a.manifested_timestamp IS NOT NULL THEN \'DISPATCHED\' WHEN a.packed_timestamp IS NOT NULL THEN \'PACKING\' ELSE \'WH_PROCESSING\' END AS overall_status FROM assembled a ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            